<script setup lang="ts">
import { onLoad } from '@dcloudio/uni-app'
import { ref } from 'vue'
import { listProperties, type Property } from '../../api/properties'
const item = ref<Property | null>(null)
onLoad(async (query) => { const items = await listProperties(); item.value = items.find((p) => p.id === query?.id) || items[0] || null })
const mediaUrl = (url: string) => url.startsWith('http') ? url : `http://150.158.157.213${url}`
</script>
<template><view v-if="item" class="page"><view v-if="!item.media?.length" class="detail-cover">🏠</view><view v-else class="media-list"><block v-for="(media, index) in item.media" :key="`${media.url}-${index}`"><image v-if="media.type === 'image'" class="media-image" :src="mediaUrl(media.url)" mode="aspectFill"/><video v-else class="media-video" :src="mediaUrl(media.url)" controls object-fit="contain"/></block></view><view class="card"><view class="price">{{ item.rentMonthly }} 元/月</view><view class="title">{{ item.title || item.community }}</view><view class="muted">{{ item.layout }} · {{ item.location }}</view><view class="tags"><text>{{ item.community }}</text><text>{{ item.feeText || '租房信息' }}</text></view></view><view class="card"><view class="title small">房源信息</view><view class="row"><text>小区</text><text>{{ item.community }}</text></view><view class="row"><text>位置</text><text>{{ item.location }}</text></view><view class="row"><text>户型</text><text>{{ item.layout }}</text></view></view><view class="card"><view class="title small">房源描述</view><view class="desc">{{ item.description || '暂无描述' }}</view></view><view class="button">电话咨询</view></view><view v-else class="page muted">房源不存在</view></template>
<style scoped>.detail-cover{height:420rpx;border-radius:28rpx;background:#dff6ef;display:flex;align-items:center;justify-content:center;font-size:160rpx}.media-list{display:flex;flex-direction:column;gap:18rpx}.media-image,.media-video{width:100%;height:420rpx;border-radius:28rpx;background:#dff6ef}.small{font-size:34rpx;margin-bottom:20rpx}.tags{display:flex;gap:16rpx;margin-top:24rpx}.tags text{padding:12rpx 22rpx;border-radius:999rpx;background:#e9faf5;color:#0f8177}.row{display:flex;justify-content:space-between;padding:22rpx 0;border-bottom:1rpx solid #eef5f2;color:#6e9a93}.row text:last-child{color:#073b3a}.desc{line-height:1.8;color:#57857e}</style>
